mapper.select:
SELECT br.id, br.book_id, br.reader_id, br.borrow_time, br.due_time, br.return_time,
       br.status, br.is_overdue,
       b.title AS book_title,
       r.name AS reader_name
FROM borrow_record br
INNER JOIN book b ON br.book_id = b.id
INNER JOIN reader r ON br.reader_id = r.id
WHERE br.is_deleted = 0

    AND br.reader_id = #{readerId}


    AND br.book_id = #{bookId}


    AND br.status = #{status}

ORDER BY br.gmt_modified DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(1)
FROM borrow_record br
WHERE br.is_deleted = 0

    AND br.reader_id = #{readerId}


    AND br.book_id = #{bookId}


    AND br.status = #{status}
